query MyCollectionArtworkQuery(
  $artworkSlug: String!
  $artistInternalID: ID!
  $medium: String!
) {
  artwork(id: $artworkSlug) {
    artist {
      internalID
      formattedNationalityAndBirthday
      id
      auctionResultsConnection(first: 3, sort: DATE_DESC) {
        totalCount
      }
    }
    consignmentSubmission {
      inProgress
    }
    artistNames
    category
    pricePaid {
      display
      minor
      currencyCode
    }
    date
    depth
    dimensions {
      in
      cm
    }
    editionSize
    editionNumber
    height
    attributionClass {
      name
      id
    }
    id
    images {
      isDefault
      imageURL
      width
      height
      internalID
    }
    internalID
    isEdition
    medium
    metric
    artworkLocation
    provenance
    slug
    title
    width
    ...NewMyCollectionArtworkHeader_artwork
    ...MyCollectionArtworkInsights_artwork
    ...MyCollectionArtworkAbout_artwork
    comparableAuctionResults(first: 6) @optionalField {
      totalCount
    }
  }
  marketPriceInsights(artistId: $artistInternalID, medium: $medium) {
    ...MyCollectionArtworkInsights_marketPriceInsights
    ...MyCollectionArtworkAbout_marketPriceInsights
    id
  }
  _marketPriceInsights: marketPriceInsights(artistId: $artistInternalID, medium: $medium) {
    annualLotsSold
    id
  }
  me {
    ...MyCollectionArtworkInsights_me
    id
  }
}

