fragment ArtistArtworks_artist_YCAiB on Artist {
  ...ArtistArtworksFilterHeader_artist
  id
  slug
  name
  internalID
  counts {
    artworks
  }
  aggregations: filterArtworksConnection(first: 0, aggregations: [COLOR, DIMENSION_RANGE, LOCATION_CITY, MAJOR_PERIOD, MATERIALS_TERMS, MEDIUM, PARTNER, PRICE_RANGE, SIMPLE_PRICE_HISTOGRAM]) {
    aggregations {
      slice
      counts {
        count
        name
        value
      }
    }
    id
  }
  artworks: filterArtworksConnection(first: $count, after: $cursor, input: $input) {
    edges {
      node {
        id
        slug
        image(includeAll: false) {
          aspectRatio
        }
        ...ArtworkGridItem_artwork_FOvjt
        __typename
      }
      cursor
    }
    pageInfo {
      endCursor
      hasNextPage
    }
    id
  }
  statuses {
    artworks
  }
}

