mutation myCollectionCreateArtworkMutation(
  $input: MyCollectionCreateArtworkInput!
) {
  myCollectionCreateArtwork(input: $input) {
    artworkOrError {
      __typename
      ... on MyCollectionArtworkMutationSuccess {
        artworkEdge {
          node {
            hasMarketPriceInsights
            artist {
              internalID
              formattedNationalityAndBirthday
              targetSupply {
                isTargetSupply
              }
              id
            }
            artistNames
            category
            collectorLocation {
              city
              state
              country
              countryCode
              id
            }
            confidentialNotes
            consignmentSubmission @optionalField {
              internalID
              isEditable
              displayText
            }
            pricePaid {
              display
              minor
              currencyCode
            }
            date
            depth
            dimensions {
              in
              cm
            }
            editionSize
            editionNumber
            height
            attributionClass {
              name
              shortDescription
              id
            }
            id
            images(includeAll: true) {
              isDefault
              imageURL
              width
              height
              internalID
            }
            internalID
            isEdition
            medium
            metric
            provenance
            slug
            title
            width
          }
        }
      }
      ... on MyCollectionArtworkMutationFailure {
        mutationError {
          message
        }
      }
    }
  }
}

