query AddToItinerarySheetQuery(
  $citySlug: String
  $first: Int!
  $sourceStopID: String!
  $sourceShareToken: String
  $hasSourceStopID: Boolean!
  $itemID: String!
  $hasShow: Boolean!
  $hasFair: Boolean!
  $hasLocation: Boolean!
) {
  sourceShow: show(id: $itemID) @include(if: $hasShow) {
    myItineraryStopMemberships {
      itineraryID
      stopIDs
    }
    id
  }
  sourceFair: fair(id: $itemID) @include(if: $hasFair) {
    myItineraryStopMemberships {
      itineraryID
      stopIDs
    }
    id
  }
  sourceLocation: location(id: $itemID) @include(if: $hasLocation) {
    myItineraryStopMemberships {
      itineraryID
      stopIDs
    }
    id
  }
  sourceStop: itineraryStop(id: $sourceStopID, shareToken: $sourceShareToken) @include(if: $hasSourceStopID) {
    myItineraryStopMemberships {
      itineraryID
      stopIDs
    }
    id
  }
  me {
    name
    itinerariesConnection(citySlug: $citySlug, first: $first) {
      edges {
        node {
          citySlug
          internalID
          title
          isCurated
          stopsCount
          heroImage {
            url(version: "small")
          }
          id
        }
      }
    }
    id
  }
}

